// ═══════════════════════════════════════════════════════════════════════
// 룬의 방 콘텐츠 — 엘더 푸사르크 24룬. 로직 없음. 화면 문구(버튼·제목)는 data.js의 TEXT.rune
//
// 결과는 돌 3개 = 지나온(우르드) · 지금(베르단디) · 다가올(스쿨드) 자리 + 주제 1개로 조립된다.
// 아래 "어디에 쓰이나"를 보고, 그 룬이 그 자리에 놓였을 때 읽힐 문장을 채운다. (N자 = 공백 포함 최대 글자 수)
//
//   code          코드용 이름. 바꾸지 말 것 (index.html 룬 획 모양 #rune-<code>와 연결)
//   glyph ~ image 기호·이름·로마자·소리·원래 뜻. image는 "원래 뜻" 줄
//   keyword       운명의 실 칸 (8자) · 공유 카드 부제 "다가올 자리: {keyword}" (20자)
//   archetype     원형 태그 (warrior sage lover rebel caregiver explorer creator ruler 중 하나. 이름은 data.js TEXT.archetypes)
//                 이 룬이 [다가올] 자리에 놓이면 이 방의 원형이 된다. 24룬을 8원형에 3개씩
//   archetypeWhy  결과 화면 "이 방에서 얻은 원형" 근거 한 줄 (60자). 이 룬이 [다가올] 자리일 때 쓰인다
//   key           캡처 카드 핵심 문장 + 공유 카드 본문 (60자, 3줄). 이 룬이 [지금] 자리일 때 쓰인다
//   identity      첫째 장(정체) 안, 룬별 소제목 아래 단락들 (룬마다 250~400자, 단락당 250자 이하). 세 자리 모두
//   past          둘째 장(사건) 앞부분 — 이 룬이 [지나온] 자리일 때
//                   lede = 둘째 장 첫 문단(강조, 80자), body = 이어지는 단락 (단락당 120~250자)
//   now           둘째 장(사건) 뒷부분 — 이 룬이 [지금] 자리일 때
//                   hook = 첫째 장 끝 떡밥 문장(45자), title = 둘째 장 제목(목차 16자),
//                   body = 단락들, quote = 인용 한 줄(50자, 장당 1개)
//   shadow        셋째 장(그림자) 전체 — 이 룬이 [다가올] 자리일 때
//                   hook = 둘째 장 끝 떡밥(45자), title(16자), lede(80자), body, quote(50자)
//   advice        넷째 장(다음) 전체 — 이 룬이 [다가올] 자리일 때
//                   hook = 셋째 장 끝 떡밥(45자), title(16자), lede(80자), body,
//                   topics = 고른 주제별 마지막 한 단락 (앞에 TEXT.rune.topics[주제].lens 문장이 붙는다)
//                   부정적인 내용이어도 넷째 장은 실행 가능한 긍정적 조언으로 끝낸다 (CLAUDE.md 8장)
//   summary       나의 이야기 6장 요약 조립용 (자리별 100~150자). 조립 모양은 TEXT.story.runeSummary
//
// 분량 목표(기획서): 한 룬 = 4,000~5,000자. 결과 한 번에는 세 룬의 서로 다른 칸이 모여 4장 합계 4,000~5,000자가 된다.
// 사건 위주 서술: 성격 나열보다 장소·시간·행동이 보이는 장면을 먼저 쓴다.
// ═══════════════════════════════════════════════════════════════════════

